 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.raw_minute_reservation_v3 r JOIN population_top3000_202608_202609_v1.pipeline_attempt a USING(attempt_id) JOIN population_top3000_202608_202609_v1.pipeline_provider_lease l USING(attempt_id) WHERE r.attempt_id=p.attempt_id AND a.task_id=t.task_id AND r.request_sha256=p.request_sha256 AND r.page_number=p.page_number AND r.request_url=p.request_url AND r.receipt=p.commit_receipt->'reservation' AND r.prior_chain_sha256=encode(sha256(convert_to(chain::text,'UTF8')),'hex') AND l.released_at IS NOT NULL AND l.received_bytes=p.wire_bytes) OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_commit k WHERE k.attempt_id=p.attempt_id AND k.task_id=t.task_id AND k.receipt=p.commit_receipt AND k.output_sha256=expected_digest AND k.commit_key='raw-page-v3:'||p.request_sha256||':'||p.page_number) THEN RAISE EXCEPTION 'RAW_VERIFY_RECEIPT_CONFLICT';END IF;
